<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedRedirectsUrlVO;

trait TrustedClientAllowedRedirectsUrlAttributeHolder
{
    protected TrustedClientAllowedRedirectsUrlVO|string|null $url = null;
    protected bool $urlAssigned = false;

    public function getUrlOrCurrent(TrustedClientAllowedRedirectsUrlVO $url): TrustedClientAllowedRedirectsUrlVO
    {
        if ($this->urlAssigned) {
            \assert(null !== $this->url);
            return TrustedClientAllowedRedirectsUrlVO::from($this->url);
        } else {
            return $url;
        }
    }
    public function urlTryBuildInitial(ConstraintFailList $error): ?TrustedClientAllowedRedirectsUrlVO
    {
        return  TrustedClientAllowedRedirectsUrlVO::tryFrom($this->urlAssigned ? $this->url : null, $error);
    }
    public function url(TrustedClientAllowedRedirectsUrlVO|string $url): static
    {
        $this->url = $url;
        $this->urlAssigned = true;
        return $this;
    }
    public function getUrl(): ?string
    {
        return $this->url instanceof TrustedClientAllowedRedirectsUrlVO ? $this->url->value() : $this->url;
    }
    public function isUrlAssigned(): bool
    {
        return $this->urlAssigned;
    }
    public function writeUrlTo(mixed $att): void
    {
        if ($this->urlAssigned) {
            \assert(null !== $this->url);
            $att->url($this->url);
        }
    }
    public function readUrlFrom(mixed $att): void
    {
        if ($att->isUrlAssigned()) {
            $url = $att->getUrl();
            \assert(null !== $url);
            $this->url($url);
        }
    }
    public function unsetUrl(): static
    {
        $this->urlAssigned = false;
        return $this;
    }
    protected function withDefaultUrl(): void
    {
    }
    protected function withAssertedUrlRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->urlAssigned = $this->urlAssigned) {
            $value->url = TrustedClientAllowedRedirectsUrlVO::tryFrom($this->url, $errorsList);
        }
    }
}
